#include <vector>
#include <unordered_map>

class Solution {
public:
    bool hasPrimeFrequency(std::vector<int>& nums) {
        std::unordered_map<int, int> counts;
        for (int x : nums) counts[x]++;

        auto is_prime = [](int val) {
            if (val < 2) return false;
            for (int d = 2; d * d <= val; ++d) {
                if (val % d == 0) return false;
            }
            return true;
        };

        for (const auto& [val, freq] : counts) {
            if (is_prime(freq)) return true;
        }
        return false;
    }
};

import java.util.*;

class Solution {
    public boolean hasPrimeFrequency(int[] nums) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : nums) counts.put(x, counts.getOrDefault(x, 0) + 1);

        for (int freq : counts.values()) {
            if (isPrime(freq)) return true;
        }
        return false;
    }

    private boolean isPrime(int val) {
        if (val < 2) return false;
        for (int d = 2; d * d <= val; d++) {
            if (val % d == 0) return false;
        }
        return true;
    }
}

