var hasPrimeFrequency = function(nums) {
    const counts = new Map();
    for (const x of nums) {
        counts.set(x, (counts.get(x) || 0) + 1);
    }

    const isPrime = (val) => {
        if (val < 2) return false;
        for (let d = 2; d * d <= val; d++) {
            if (val % d === 0) return false;
        }
        return true;
    };

    for (const freq of counts.values()) {
        if (isPrime(freq)) return true;
    }
    return false;
};
